'use client'
import { useEffect, useLayoutEffect, useRef, useState } from 'react'
import { BarChart } from '@/components/ui/BarChart'
import { LineChart, type LineSeries } from '@/components/ui/LineChart'
import { Tabs } from '@/components/ui/Tabs'
import { formatNumber } from '@/hooks/useChart'
import { runTransition } from '@/lib/transition'

// Overview's Queries card (platform/Queries.vue): volume or latency, three numbers over the chart (the chart item:
// BarChart for queries per day, LineChart for the last 24 hours' latency). Pointing at a number shows its part (this
// month's bars, today's bar, or the latency); a press pins it, with a 2px red edge. Nothing navigates: the chart changes
// in place, crossing over in 200ms. `latency` is the chart's series (p50, p95), each point a time and milliseconds.
export interface QueryDay { day: string, value: number }
export interface OverviewQueriesProps { thisMonth: number, p50: number, p95: number, days: QueryDay[], latency: LineSeries[] }
type Stat = '' | 'month' | 'today' | 'latency'
type View = 'volume' | 'latency'
const ms = (v: number) => `${Math.round(v)} ms`

export function OverviewQueries({ thisMonth, p50, p95, days, latency }: OverviewQueriesProps) {
  const [chart, setChart] = useState<View>('volume')
  const [pinned, setPinned] = useState<Stat>('')
  const [hot, setHot] = useState<Stat>('')
  const active = hot || pinned
  const view: View = active === 'latency' ? 'latency' : active ? 'volume' : chart
  function pin(stat: Exclude<Stat, ''>) {
    setPinned(pinned === stat ? '' : stat)
    setChart(stat === 'latency' ? 'latency' : 'volume')
  }
  const setTab = (v: View) => { setChart(v); setPinned('') }
  const today = days.at(-1)?.value ?? 0
  const month = days.at(-1)?.day.slice(0, 7) ?? ''
  const focus = active === 'today' ? (days.length ? [days.length - 1] : []) : active === 'month' ? days.flatMap((d, i) => (d.day.startsWith(month) ? [i] : [])) : undefined
  const note = active === 'today' ? `Today ${formatNumber(today)}` : active === 'month' ? `${new Date(`${month}-01T00:00:00Z`).toLocaleString('en-US', { month: 'long', timeZone: 'UTC' })} so far` : undefined

  // Vue's <Transition mode="out-in"> keyed by the view: the chart shown leaves, then the next enters.
  const [shown, setShown] = useState<View>(view)
  const box = useRef<HTMLDivElement | null>(null)
  const entering = useRef(false)
  useEffect(() => {
    if (view === shown) return
    const node = box.current
    if (!node) return setShown(view)
    let done = false
    void runTransition(node, 'ds-ovchart', 'leave').then(() => {
      if (done) return
      entering.current = true
      setShown(view)
    })
    return () => { done = true }
  }, [view, shown])
  useLayoutEffect(() => {
    if (!entering.current || !box.current) return
    entering.current = false
    void runTransition(box.current, 'ds-ovchart', 'enter')
  }, [shown])

  const stats = [['month', 'This month', formatNumber(thisMonth)], ['today', 'Today', formatNumber(today)], ['latency', 'Search p50, 24 h', `${p50} ms`]] as const
  return (
    <>
      <style href="ds-overview-queries" precedence="ds">{css}</style>
      <section data-ds="overview-queries" className="min-w-0 border border-edge bg-surface" aria-labelledby="queries-title">
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 border-b border-edge px-4 py-3">
          <h2 id="queries-title" className="type-ui-strong">Queries</h2>
          <Tabs value={view} onValueChange={setTab} options={[{ value: 'volume', label: 'Volume' }, { value: 'latency', label: 'Latency' }]} label="chart" />
        </div>
        <div className="flex flex-col gap-4 p-4">
          <div className="grid grid-cols-2 border-t border-l border-edge sm:grid-cols-3">
            {stats.map(s => (
              <button key={s[0]} type="button" className="ds-ovstat" aria-pressed={pinned === s[0]} data-on={active === s[0] || undefined} onClick={() => pin(s[0])} onPointerEnter={() => setHot(s[0])} onPointerLeave={() => setHot('')}>
                <span className="block type-meta text-fg-muted">{s[1]}</span>
                <span className="block text-heading-4 font-medium tabular-nums">{s[2]}{s[0] === 'latency' && <span className="ml-2 type-meta text-fg-muted">{`p95 ${p95} ms`}</span>}</span>
              </button>
            ))}
          </div>
          <div key={shown} ref={box}>
            {shown === 'volume' && days.some(d => d.value > 0)
              ? <BarChart points={days} label="Queries per day" height={192} focus={focus} note={note} />
              : shown === 'volume'
                ? <p className="py-8 text-center type-meta text-fg-muted">No queries yet.</p>
                : latency.some(l => l.points.length)
                  ? <LineChart title="Search latency, last 24 hours" series={latency} format={ms} smooth={3} height={192} bare />
                  : <p className="py-8 text-center type-meta text-fg-muted">No searches in the last 24 hours.</p>}
          </div>
        </div>
      </section>
    </>
  )
}

export default OverviewQueries

const css = `
.ds-ovstat { position: relative; width: 100%; padding: 8px 12px; border-right: var(--ds-border-hairline) solid var(--ds-color-edge); border-bottom: var(--ds-border-hairline) solid var(--ds-color-edge); text-align: left; cursor: pointer; transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-ovstat[data-on] { background: var(--ds-color-surface-subtle); }
@media (hover: hover) and (pointer: fine) { .ds-ovstat:hover { background: var(--ds-color-surface-subtle); } }
.ds-ovstat[aria-pressed="true"]::before { position: absolute; top: -1px; right: -1px; left: -1px; height: 2px; background: var(--ds-color-edge-accent); content: ""; }
.ds-ovstat:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-focus); outline-offset: -2px; }
.ds-ovchart-enter-active { transition: opacity var(--ds-duration-enter) var(--ds-easing-out), transform var(--ds-duration-drawer) var(--ds-easing-out); }
.ds-ovchart-leave-active { transition: opacity var(--ds-duration-exit) var(--ds-easing-standard), transform var(--ds-duration-exit) var(--ds-easing-standard); }
.ds-ovchart-enter-from { opacity: 0; transform: translateY(6px); }
.ds-ovchart-leave-to { opacity: 0; transform: translateY(-4px); }
@media (prefers-reduced-motion: reduce) {
  .ds-ovchart-enter-from, .ds-ovchart-leave-to { transform: none; }
}
`

'use client'
import { useEffect, useRef, useState, type ComponentType, type MouseEvent, type ReactNode } from 'react'
import { Menu as MenuIcon, X } from 'lucide-react'
import { Breadcrumb, type Crumb } from '@/components/ui/Breadcrumb'
import { Sidebar } from '@/components/ui/Sidebar'
import { SidebarLabel } from '@/components/ui/SidebarLabel'
import { SidebarLink } from '@/components/ui/SidebarLink'
import { TopBar } from '@/components/ui/TopBar'

// The console's layout (layouts/console.vue) for page compositions: the Sidebar at the left, sticky at the screen's
// height, the TopBar with the trail over the page. Below 768px the sidebar is a drawer: the bar's menu button slides
// it in over a dimmed page (240ms in, 180ms out, on the strong ease-out), a tap on the page or Escape closes it.
// `head` takes the workspace switcher, `foot` the account menu, `bar` what sits at the bar's end.
export interface FrameLink { label: string, icon?: ComponentType<{ size?: number, strokeWidth?: number }>, href?: string, status?: string, alert?: boolean, active?: boolean }
export interface FrameGroup { label: string, links: FrameLink[] }
export interface ConsoleFrameProps {
  groups: FrameGroup[]
  crumbs: Crumb[]
  onNavigate?: (link: FrameLink) => void
  /** The workspace switcher (Vue's `head` slot). */
  head?: ReactNode
  /** The account menu (Vue's `foot` slot). */
  foot?: ReactNode
  /** What sits at the bar's end (Vue's `bar` slot). */
  bar?: ReactNode
  children?: ReactNode
}

export function ConsoleFrame({ groups, crumbs, onNavigate, head, foot, bar, children }: ConsoleFrameProps) {
  const [open, setOpen] = useState(false)
  const root = useRef<HTMLDivElement | null>(null)
  // Vue's data-open falls through to the Sidebar's root; Sidebar takes no extra attributes, so it is set here.
  useEffect(() => {
    root.current?.querySelector('[data-ds="sidebar"]')?.toggleAttribute('data-open', open)
  }, [open])
  function go(link: FrameLink, event: MouseEvent) {
    event.preventDefault()
    setOpen(false)
    onNavigate?.(link)
  }
  return (
    <>
      <style href="ds-console-frame" precedence="ds">{css}</style>
      <div data-ds="console-frame" ref={root} className="flex min-h-screen bg-surface" onKeyDown={(e) => { if (e.key === 'Escape') setOpen(false) }}>
        <Sidebar label="console" className="ds-frame-side shrink-0" head={head} foot={foot}>
          {groups.map(group => [
            <SidebarLabel key={`l-${group.label}`}>{group.label}</SidebarLabel>,
            ...group.links.map(link => <SidebarLink key={`${group.label}-${link.label}`} href={link.href ?? '#'} icon={link.icon} status={link.status} alert={link.alert} active={link.active} onClick={e => go(link, e)}>{link.label}</SidebarLink>),
          ])}
        </Sidebar>
        {open && <div className="fixed inset-0 z-20 bg-scrim-light md:hidden" aria-hidden="true" onClick={() => setOpen(false)} />}
        <div className="flex min-w-0 flex-1 flex-col">
          <TopBar
            start={(
              <button type="button" className="-ml-2 inline-flex size-control-touch shrink-0 cursor-pointer items-center justify-center border border-transparent text-fg-soft transition-[color,border-color] duration-120 ease-standard hover:border-edge hover:text-fg md:hidden" aria-expanded={open} aria-label={open ? 'close menu' : 'open menu'} onClick={() => setOpen(o => !o)}>
                {open ? <X size={14} strokeWidth={1.5} /> : <MenuIcon size={14} strokeWidth={1.5} />}
              </button>
            )}
            end={bar}
          >
            <Breadcrumb items={crumbs} onNavigate={(_, e) => e.preventDefault()} />
          </TopBar>
          <main className="min-w-0 flex-1">{children}</main>
        </div>
      </div>
    </>
  )
}

export default ConsoleFrame

const css = `
@media (min-width: 768px) { .ds-frame-side { position: sticky; top: 0; height: 100vh; } }
@media (max-width: 767px) {
  .ds-frame-side { position: fixed; top: 0; bottom: 0; left: 0; z-index: 30; width: min(300px, 84vw); overscroll-behavior: contain; visibility: hidden; transform: translateX(-100%); transition: transform var(--ds-duration-slide) var(--ds-easing-out), visibility 0s linear var(--ds-duration-slide); }
  .ds-frame-side[data-open] { visibility: visible; transform: none; transition: transform var(--ds-duration-drawer) var(--ds-easing-out); }
}
@media (prefers-reduced-motion: reduce) { .ds-frame-side, .ds-frame-side[data-open] { transition: none; } }
`

import type { ReactNode } from 'react'

// The frame of every console page (Page.vue, .v2-page .v2-page-wide): 1120px at most, 32px down and 16px in on a
// phone (40px and 32px from 768px), the title in Faculty Glyphic 20px (or Geist Mono when it is an identifier, shown
// as typed), the page's actions on the right, then the body in 24px steps.
export interface ConsolePageProps {
  title: string
  mono?: boolean
  /** Beside the title (Vue's `meta` slot). */
  meta?: ReactNode
  /** The page's actions on the right (Vue's `actions` slot). */
  actions?: ReactNode
  children?: ReactNode
  /** The root's data-ds (a page built on this one says its own, as Vue's fallthrough does). */
  'data-ds'?: string
}

export function ConsolePage({ title, mono, meta, actions, children, 'data-ds': ds = 'console-page' }: ConsolePageProps) {
  return (
    <div data-ds={ds} className="mx-auto w-full max-w-page-wide px-4 pt-8 pb-16 md:px-8 md:pt-10 md:pb-20">
      <header className="mb-6 flex min-h-8 flex-wrap items-center justify-between gap-x-6 gap-y-3">
        <div className="flex min-w-0 flex-wrap items-center gap-x-4 gap-y-2">
          <h1 className={mono ? 'min-w-0 font-code text-heading-3 leading-8 font-medium [overflow-wrap:anywhere]' : 'min-w-0 type-heading-3'}>{title}</h1>
          {meta}
        </div>
        {actions && (
          <div className="flex flex-wrap items-center gap-2">
            {actions}
          </div>
        )}
      </header>
      <div className="flex flex-col gap-6">
        {children}
      </div>
    </div>
  )
}

export default ConsolePage

// What the charts share (usageMetrics.ts, BarChart.vue): numbers in en-US, an axis that ends on a round number in four
// steps, and the week's change.

export type DayPoint = { day: string, value: number }
export type ChartMetric = { key: string, label: string, points: DayPoint[] }

const whole = new Intl.NumberFormat('en-US')
const compact = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 })

/** 186402 -> "186,402". */
export const formatNumber = (n: number) => whole.format(n)
/** 186402 -> "186.4K", for axis labels. */
export const compactNumber = (n: number) => compact.format(n)

/** The axis: a step of 1, 2, 2.5 or 5 times a power of ten that covers the largest value in four. Starts at 0. */
export function niceTicks(values: number[]) {
  const max = Math.max(0, ...values)
  if (max === 0) return [0, 1]
  const raw = max / 4
  const power = 10 ** Math.floor(Math.log10(raw))
  const step = ([1, 2, 2.5, 5, 10].find(m => m * power >= raw) ?? 10) * power
  return Array.from({ length: Math.ceil(max / step) + 1 }, (_, i) => i * step)
}

/** "Oct 2", or "Oct 2, 2026" with the year, from an ISO day. */
export const formatDay = (value: string, year = false) => new Date(`${value}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', ...(year ? { year: 'numeric' } : {}), timeZone: 'UTC' })

/** The sum of a metric's points over its range. */
export const totalOf = (points: DayPoint[]) => points.reduce((a, p) => a + p.value, 0)

/** The last seven days against the seven before, as a share; null without both. */
export function weekChange(points: DayPoint[]): number | null {
  if (points.length < 14) return null
  const before = totalOf(points.slice(-14, -7))
  return before ? (totalOf(points.slice(-7)) - before) / before : null
}

'use client'
import { Children, cloneElement, isValidElement, useLayoutEffect, useRef, useState, type ReactElement, type ReactNode, type Ref } from 'react'
import { flushSync } from 'react-dom'

// Vue's <Transition> and <TransitionGroup> for the React flavor, with the same class names, so a Vue item's CSS
// (.ds-pop-enter-from, .ds-toast-leave-active, .ds-toast-move...) works unchanged:
//
//   <Transition show={open} name="ds-pop">{<div ... />}</Transition>
//   <TransitionGroup name="ds-toast">{toasts.map((t) => <p key={t.id} ... />)}</TransitionGroup>
//
// Entering: <name>-enter-from and -enter-active, then a frame later -enter-to in place of -enter-from, until the
// transition ends. Leaving: the same with -leave-*, and the element stays until it has, then goes in the same task its
// classes come off (flushSync), so it never shows again for a frame. A group also moves the others with <name>-move
// (FLIP), measured once the entering and leaving children have their classes, as Vue's are. `css={false}` skips the classes (Vue's :css="false"); `duration` is Vue's explicit duration
// in ms, a number or { enter, leave }. The child must take a ref (a DOM element) and className.
type Duration = number | { enter: number, leave: number }
type Phase = 'enter' | 'leave'

const ms = (d: Duration | undefined, phase: Phase) => (d === undefined ? undefined : typeof d === 'number' ? d : d[phase])

/** Runs one Vue transition phase on an element and resolves when it has ended. */
export function runTransition(el: HTMLElement, name: string, phase: Phase, duration?: Duration): Promise<void> {
  const from = `${name}-${phase}-from`
  const active = `${name}-${phase}-active`
  const to = `${name}-${phase}-to`
  el.classList.add(from, active)
  return new Promise((resolve) => {
    let done = false
    const finish = () => {
      if (done) return
      done = true
      el.classList.remove(from, active, to)
      el.removeEventListener('transitionend', onEnd)
      el.removeEventListener('animationend', onEnd)
      resolve()
    }
    const onEnd = (event: Event) => { if (event.target === el) finish() }
    requestAnimationFrame(() => requestAnimationFrame(() => {
      el.classList.remove(from)
      el.classList.add(to)
      const explicit = ms(duration, phase)
      if (explicit !== undefined) return void setTimeout(finish, explicit)
      // The longest transition or animation on it, as Vue reads it; none means done now.
      const cs = getComputedStyle(el)
      const longest = (durations: string, delays: string) => {
        const d = durations.split(',').map(s => Number.parseFloat(s) * (s.trim().endsWith('ms') ? 1 : 1000))
        const l = delays.split(',').map(s => Number.parseFloat(s) * (s.trim().endsWith('ms') ? 1 : 1000))
        return Math.max(0, ...d.map((x, i) => x + (l[i % l.length] || 0)))
      }
      const total = Math.max(longest(cs.transitionDuration, cs.transitionDelay), longest(cs.animationDuration, cs.animationDelay))
      if (!total) return finish()
      el.addEventListener('transitionend', onEnd)
      el.addEventListener('animationend', onEnd)
      setTimeout(finish, total + 50)
    }))
  })
}

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>) {
  return (node: T) => {
    for (const r of refs) {
      if (typeof r === 'function') r(node)
      else if (r) (r as { current: T }).current = node
    }
  }
}
type Child = ReactElement<{ ref?: Ref<HTMLElement>, className?: string }>

export interface TransitionProps { show: boolean, name: string, css?: boolean, duration?: Duration, appear?: boolean, children: ReactNode }

/** Vue's <Transition> around one element: it enters when `show` turns true and leaves before it unmounts. */
export function Transition({ show, name, css = true, duration, appear, children }: TransitionProps) {
  // Whether the element is in the page: from the render where `show` turns true until its leave has ended.
  const [present, setPresent] = useState(show)
  const el = useRef<HTMLElement | null>(null)
  const was = useRef<boolean | null>(null)
  const last = useRef<ReactNode>(children)
  if (show) last.current = children
  if (show && !present) setPresent(true)
  useLayoutEffect(() => {
    const before = was.current
    was.current = show
    const node = el.current
    if (before === show) return
    if (show) {
      if (node && css && (before !== null || appear)) void runTransition(node, name, 'enter', duration)
    }
    // Gone in the same task its leave classes come off, as Vue removes it, so no frame shows it whole again.
    else if (node && css && before) void runTransition(node, name, 'leave', duration).then(() => { if (!was.current) flushSync(() => setPresent(false)) })
    else setPresent(false)
  }, [show]) // eslint-disable-line react-hooks/exhaustive-deps
  const child = (show ? children : last.current) as Child
  if (!(show || present) || !isValidElement(child)) return null
  return cloneElement(child, { ref: mergeRefs(child.props.ref, (n: HTMLElement | null) => { el.current = n }) })
}

export interface TransitionGroupProps { name: string, children: ReactNode }

/** Vue's <TransitionGroup>: keyed children enter and leave as <Transition> does, and the rest move with <name>-move. */
export function TransitionGroup({ name, children }: TransitionGroupProps) {
  const nodes = useRef(new Map<string, HTMLElement>())
  const rects = useRef(new Map<string, DOMRect>())
  const seen = useRef(new Set<string>())
  const firstRender = useRef(true)
  const current = Children.toArray(children).filter(isValidElement) as Child[]
  const [leaving, setLeaving] = useState<Map<string, { child: Child, index: number }>>(new Map())
  const prev = useRef<Child[]>([])

  // Children that went away stay, leaving, where they were.
  const keys = new Set(current.map(c => c.key!))
  const gone = prev.current.filter(c => !keys.has(c.key!) && !leaving.has(c.key!))
  if (gone.length) {
    const next = new Map(leaving)
    for (const c of gone) next.set(c.key!, { child: c, index: prev.current.indexOf(c) })
    setLeaving(next)
  }
  prev.current = current
  const list = [...current]
  for (const [key, { child, index }] of leaving) if (!keys.has(key)) list.splice(Math.min(index, list.length), 0, child)

  // Before the DOM changes: where every child is now (for the move).
  for (const [key, node] of nodes.current) rects.current.set(key, node.getBoundingClientRect())

  useLayoutEffect(() => {
    // First every entering and leaving child takes its classes, so the measures for the move below see each as Vue does
    // (an entering one at its enter-from, a leaving one out of the flow): measuring first would fix an entering child's
    // style as it is, fully shown, and its transition would start from the end.
    const entered = new Set<string>()
    for (const c of list) {
      const key = c.key!
      const node = nodes.current.get(key)
      if (!node) continue
      if (leaving.has(key)) {
        if (!node.classList.contains(`${name}-leave-active`)) {
          // Gone in the same task its leave classes come off, so no frame shows it whole again.
          void runTransition(node, name, 'leave').then(() => flushSync(() => setLeaving((m) => {
            const n = new Map(m)
            n.delete(key)
            return n
          })))
        }
        continue
      }
      if (!seen.current.has(key)) {
        seen.current.add(key)
        entered.add(key)
        if (!firstRender.current) void runTransition(node, name, 'enter')
      }
    }
    // Then the move: from where each stayed child was to where it is.
    for (const c of list) {
      const key = c.key!
      const node = nodes.current.get(key)
      if (!node || leaving.has(key) || entered.has(key)) continue
      const before = rects.current.get(key)
      if (!before) continue
      const after = node.getBoundingClientRect()
      if (before.left !== after.left || before.top !== after.top) {
        node.style.transitionDuration = '0s'
        node.style.transform = `translate(${before.left - after.left}px, ${before.top - after.top}px)`
        void node.offsetWidth
        node.classList.add(`${name}-move`)
        node.style.transitionDuration = ''
        node.style.transform = ''
        const end = () => {
          node.classList.remove(`${name}-move`)
          node.removeEventListener('transitionend', end)
        }
        node.addEventListener('transitionend', end)
      }
    }
    firstRender.current = false
    for (const key of [...seen.current]) if (!list.some(c => c.key === key)) seen.current.delete(key)
  })

  return (
    <>
      {list.map(c => cloneElement(c, {
        key: c.key,
        ref: mergeRefs(c.props.ref, (n: HTMLElement | null) => {
          if (n) nodes.current.set(c.key!, n)
          else nodes.current.delete(c.key!)
        }),
      }))}
    </>
  )
}
